glsl:
vec4 effect(vec2 uv) {
  float fr = floor(uTime * 18.0);
  vec2 j = vec2(0.0, (hash(vec2(fr, 1.0)) - 0.5) * 0.004);
  vec3 c = getColor(uv + j).rgb;
  float l = luma(c);
  vec3 sep = vec3(l * 1.07, l * 0.95, l * 0.75);
  vec3 col = mix(c, sep, uAmount);
  col *= 0.88 + 0.12 * hash(vec2(fr, 3.0));
  float sx = hash(vec2(floor(uTime * 9.0), 5.0));
  col *= 1.0 - step(abs(uv.x - sx), 0.0012) * 0.6 * uAmount;
  float dust = step(0.9985, hash(floor(uv * vec2(320.0, 180.0)) + fr));
  col = mix(col, vec3(0.1), dust * uAmount);
  vec2 d = uv - 0.5;
  col *= 1.0 - smoothstep(0.3, 0.75, length(d)) * 0.7 * uAmount;
  return vec4(col, getColor(uv).a);
}
